import React, { useEffect, useState } from 'react';
import axios from 'axios';
import './ProductList.css';

const ProductList = () => {
  const [products, setProducts] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    fetchProducts();
  }, []);

  const fetchProducts = async () => {
    try {
      const response = await axios.get('http://localhost:8080/api/products');
      setProducts(response.data);
      setLoading(false);
    } catch (err) {
      setError('Failed to fetch products. Please try again.');
      setLoading(false);
    }
  };

  if (loading) {
    return (
      <div className="loading">
        <div className="spinner"></div>
        <p>Loading products...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="error">
        <p>{error}</p>
        <button onClick={fetchProducts}>Retry</button>
      </div>
    );
  }

  return (
    <div className="product-list">
      <h2>Our Fresh Products</h2>
      {products.length === 0 ? (
        <p className="no-products">No products available at the moment. Please check back later!</p>
      ) : (
        <div className="products">
          {products.map((product) => (
            <div key={product.id} className="product-card">
              <h3>🌾 {product.name || 'N/A'}</h3>
              <p><strong>Price:</strong> ₹{product.price || 'N/A'}</p>
              <p><strong>Quantity:</strong> {product.quantity || 'N/A'}</p>
              <p>{product.description || 'No description available'}</p>
              <p><strong>Listed on:</strong> {product.listingDate || 'N/A'}</p>
              <p><strong>Farmer:</strong> {product.farmer?.name || 'Unknown'}</p>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default ProductList;
